        val importEqualsDeclaration: ImportEqualsDeclaration? = promotedDeclaration.asImportEqualsDeclaration()
        if (com.xemantic.typescript.tsgo.ast.isExternalModuleReference(importEqualsDeclaration!!.moduleReference)) {
            val expr: Node? = importEqualsDeclaration!!.moduleReference.expression()
            if (expr != null) {
                if (com.xemantic.typescript.tsgo.ast.isStringLiteralLike(expr)) {
                    return expr.text()
                }
                return com.xemantic.typescript.tsgo.scanner.getTextOfNode(expr)
            }
        }
        return com.xemantic.typescript.tsgo.scanner.getTextOfNode(importEqualsDeclaration!!.moduleReference)
    }
    val moduleSpecifier: Node? = promotedDeclaration!!.parent.moduleSpecifier()
    if (com.xemantic.typescript.tsgo.ast.isStringLiteralLike(moduleSpecifier)) {
        return moduleSpecifier.text()
    }
    return com.xemantic.typescript.tsgo.scanner.getTextOfNode(moduleSpecifier)
}

